#!/usr/bin/env python3
"""Append a late-game order-trim wrapper to a base agent, one file per rule set.

Each spec is NAME=LO-HI:OP:ITEM:CAP[;LO-HI:OP:ITEM:CAP...]. For market orders of
type OP on ITEM at steps LO..HI (inclusive) the quantity is capped at CAP
(CAP 0 drops the order).
"""
from __future__ import annotations

import argparse
from pathlib import Path

WRAPPER = '''

# ---- late order trims (generated by scripts/make_late_rule_variants.py) ----
_LT_RULES = {rules!r}
_LT_REPORT = {{"lt_trims": 0, "lt_errors": 0}}
_LT_BASE = [_v for _v in list(globals().values()) if callable(_v)][-1]


def late_trim_agent(observation, configuration=None):
    action = _LT_BASE(observation, configuration)
    try:
        step = int(_get(observation, "step", 0) or 0)
        if not isinstance(action, dict):
            return action
        rules = [r for r in _LT_RULES if r[0] <= step <= r[1]]
        if not rules:
            return action
        market = []
        changed = False
        for o in (action.get("market") or []):
            if o and len(o) >= 3:
                cap = None
                for lo, hi, op, item, c in rules:
                    if o[0] == op and o[1] == item:
                        cap = c if cap is None else min(cap, c)
                if cap is not None and int(o[2]) > cap:
                    changed = True
                    if cap > 0:
                        market.append([o[0], o[1], cap])
                    continue
            market.append(o)
        if changed:
            _LT_REPORT["lt_trims"] += 1
            return dict(action, market=market)
        return action
    except Exception:
        _LT_REPORT["lt_errors"] += 1
        return action


late_trim_agent.telemetry = _LT_REPORT
'''


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--base", required=True)
    ap.add_argument("--out-dir", required=True)
    ap.add_argument("specs", nargs="+")
    a = ap.parse_args()
    src = Path(a.base).read_text()
    out = Path(a.out_dir); out.mkdir(parents=True, exist_ok=True)
    for spec in a.specs:
        name, body = spec.split("=", 1)
        rules = []
        for part in body.split(";"):
            rng, op, item, cap = part.split(":")
            lo, hi = rng.split("-")
            rules.append((int(lo), int(hi), op, item, int(cap)))
        (out / f"{name}.py").write_text(src.rstrip("\n") + "\n" + WRAPPER.format(rules=tuple(rules)))
        print("wrote", out / f"{name}.py", rules)


if __name__ == "__main__":
    main()
